reference_solution:
def distribute_candies_three_children(n,limit):
    if n>3*limit:return 0
    def choose2(value):return value*(value-1)//2 if value>=2 else 0
    answer=choose2(n+2)-3*choose2(n-limit+1)+3*choose2(n-2*limit)
    return max(0,answer)

